// Settings, in one place: every event passes through here.
// Landbright's machine API (the Landbright API credential holds the application's client credentials):
const LANDBRIGHT_URL = 'http://127.0.0.1:4401';
// Landledger's console, for the link Landbright shows with the gate's answer:
const LANDLEDGER_CONSOLE_URL = 'http://localhost:4811';
// Only for a Landbright that doesn't say what a request costs (its request's costs): a bundle's name → the app key a
// Landledger contract names (Landledger → Contracts, landbrightApp). Landbright with spec 008 needs nothing here.
const SEAT_APPS = {};
// Settle Landbright's cost gate (step 0, settled by this flow's Landbright application with steps:settle) from
// Landledger's decision: POST /api/v1/requests/:id/steps/0/settle. Verified against Landbright's PR #5 (spec 008), not
// merged yet: off until it is. Off, the flow only notes the decision on the Landbright request, and a request whose
// gate nobody settles expires in Landbright after the gate's deadline (the flow then cancels or releases the seat).
const SETTLE_IN_LANDBRIGHT = false;
return { ...$json, settings: { landbrightUrl: LANDBRIGHT_URL.replace(/\/+$/, ''), landledgerConsoleUrl: LANDLEDGER_CONSOLE_URL.replace(/\/+$/, ''), seatApps: SEAT_APPS, settleInLandbright: SETTLE_IN_LANDBRIGHT } };

// Landbright's events arrive as a signed JWT (the event in jwtPayload.event: trust that, not the body); Landledger's
// through the Landledger Trigger; the reconcile from Every hour. 0: an access request was made (raise the cost);
// 1: Landledger decided the cost; 2: Landbright decided the access, or a grant moved (apply or release the seat);
// 3: the hourly reconcile. Anything else stops here.
const settings = $json.settings;
const e = $json.jwtPayload?.event;
if (e) {
  const type = String(e.type ?? '');
  // grant.* carries the request in data.requestId; request.created says what it costs (costs) and whether a gate waits
  // on a system (waitsOn); request.decided says outcome, and waitedOn when a gate ran out.
  const landbrightRequestId = type.startsWith('request.') ? (e.target?.id ?? null) : (e.data?.requestId ?? null);
  const route = !landbrightRequestId ? null : type === 'request.created' ? 0 : type === 'request.decided' || type.startsWith('grant.') ? 2 : null;
  if (route === null) return [];
  const d = e.data ?? {};
  return { route, source: 'landbright', eventType: type, landbrightRequestId, costs: d.costs ?? [], waitsOn: d.waitsOn ?? null, outcome: d.outcome ?? null, waitedOn: d.waitedOn ?? null, settings };
}
if ($json.type === 'request.decided' && $json.kind === 'tool_or_seat') {
  return { route: 1, source: 'landledger', eventType: $json.type, requestId: $json.requestId, outcome: $json.outcome, settings };
}
if (!$json.type && ($json.scheduledAt || $json.firedAt)) return { route: 3, source: 'schedule', eventType: 'reconcile', settings };
return [];

parameters.code:
// Does this access cost a seat? Landbright's state decides, not the event: the request's costs (spec 008; the event's,
// or SEAT_APPS for an older Landbright). Raised for a request pending at the gate; one Landbright already granted under
// break-glass (it skipped the gate: the cost is raised afterwards, as break-glass); an extension pending at the gate
// (Extension or new seat? decides whether it rides on the first request's seat); and an extension approved after its
// grant ended, which Landbright answers with a new grant: that grant needs a seat request of its own.
const event = $('What happened').first().json;
const settings = event.settings;
const r = $input.first().json;
const ext = r.extends ?? null;
const breakGlass = !ext && (r.method === 'break_glass' || (r.breakGlass !== null && r.breakGlass !== undefined));
const newGrant = Boolean(ext && r.status === 'approved' && r.grant?.status === 'active' && r.grant.id !== ext.grantId);
if (ext ? r.status !== 'pending' && !newGrant : breakGlass ? r.status !== 'approved' : r.status !== 'pending') return [];
const app = r.costs?.find((c) => c.kind === 'seat')?.landbrightApp ?? event.costs?.[0] ?? settings.seatApps[r.bundle?.name] ?? null;
if (!app) return [];
const subject = r.subject ?? r.requester;
const gate = r.steps?.[0];
return [{ json: {
  landbrightRequestId: r.id,
  ref: r.ref,
  url: r.decisionUrl,
  app,
  bundle: r.bundle?.name ?? '',
  breakGlass,
  // An extension at the gate: the grant it adds time to, the request that grant came from, and the time it adds.
  extension: ext && !newGrant ? { grantId: ext.grantId, ref: ext.ref, durationMinutes: Number(r.durationMinutes ?? 0) } : null,
  newGrant,
  about: ext ? ` (an extension of ${ext.ref}${newGrant ? ', approved after its grant ended' : ''})` : '',
  gateWaiting: gate?.kind === 'external' && gate.system === 'Landledger' && r.status === 'pending' && r.currentStep === 0 && !gate.settlement,
  waitsOn: r.waitingOnSystem ?? event.waitsOn ?? null,
  // Landledger finds the person by their Landbright subject; they confirm the request in their own session.
  requester: r.requester?.id ?? r.requester?.email,
  subject: subject?.displayName ?? subject?.email ?? 'someone',
} }];

// One seat request per Landbright request (idempotency key landbright-<REQ-n>). A redelivered event starts another run,
// whose request carries another origin, so Landledger answers 409 for the same key, naming the request it already has
// (its details.requestId, which the node puts in the message). The run that raised it may have stopped before recording
// it: 1 reads the request Landledger named, 2 (a Landledger that names none) finds it by its origin among this key's
// seat requests; either is recorded. Any other failure stops the run.
const item = $input.first().json;
const failed = item.error ? String(item.error.message ?? item.error) : '';
if (failed && !/Landledger API error 409/.test(failed)) throw new Error(failed);
if (!failed) return [{ json: { route: 0, request: item.request, executionId: $execution.id, recovered: false } }];
const named = /\(request ([A-Za-z0-9_-]+)\)/.exec(failed)?.[1] ?? null;
return [{ json: { route: named ? 1 : 2, requestId: named, existingId: named, why: failed } }];

// Trust a decision only for a seat request this flow raised: created by this flow's key, a tool_or_seat, and recorded
// by the run of this workflow its origin names. 0: the cost is approved; 1: rejected, cancelled or expired; 2: refused.
const event = $('What happened').first().json;
const settings = event.settings;
const r = $('Get the request').first().json.request;
const me = $('Who is this flow').first().json;
const rows = $input.all().map((i) => i.json).filter((x) => x.landledger_request_id === r.id);
// The run that raised it: the origin, or, for a break-glass cost (its origin is the Landbright request), a related source.
const breakGlass = r.origin?.type === 'landbright_request' && r.origin.breakGlass === true;
const run = breakGlass ? (r.related ?? []).find((x) => x.type === 'landflow_run') : r.origin;
const row = rows.find((x) => x.execution_id === run?.executionId);
const problems = [];
if (r.createdBy?.kind !== 'key' || !me.id || r.createdBy.id !== me.id) problems.push(`raised by ${r.createdBy?.name ?? 'someone else'}, not this flow's key (${me.name ?? 'unknown'})`);
if (r.kind !== 'tool_or_seat') problems.push(`a ${r.kind} request, not a tool_or_seat`);
if (run?.type !== 'landflow_run' || run.workflowId !== $workflow.id) problems.push('its origin is another workflow');
else if (!row) problems.push(rows.length ? `its origin names run ${run.executionId}, but another run recorded it` : 'no run of this workflow raised it');
else if (breakGlass && row.landbright_ref !== r.origin.id) problems.push(`its origin names ${r.origin.id}, but the run recorded ${row.landbright_ref}`);
const approved = event.outcome === 'approved';
if (!problems.length && approved && !['approved', 'applied'].includes(r.status)) problems.push(`Landledger says it is ${r.status} now, not approved`);
const decision = (r.decisions ?? []).at(-1);
const reason = approved ? '' : decision?.comment ? `${decision.person?.name ?? 'The approver'}: ${decision.comment}` : `the cost request was ${event.outcome ?? r.status}`;
return [{ json: {
  route: problems.length ? 2 : approved ? 0 : 1,
  why: problems.join('; '),
  outcome: approved ? 'approved' : 'denied',
  landledgerRequestId: r.id,
  number: r.number,
  seat: r.seat ?? null,
  landbrightRequestId: row?.landbright_request_id ?? null,
  landbrightRef: row?.landbright_ref ?? null,
  reason,
  breakGlass,
  app: row?.app ?? null,
  contractId: r.seat?.contractId ?? null,
  settle: settings.settleInLandbright === true,
  landbrightUrl: settings.landbrightUrl,
  landledgerUrl: `${settings.landledgerConsoleUrl}/requests/${r.id}`,
} }];

// What Landbright needs now, from its request as it stands. 0: settle the cost gate (step 0, waiting on Landledger, and
// SETTLE_IN_LANDBRIGHT on); 1: the seat is in use already (granted before the cost was approved: break-glass, or an
// extension's new grant): mark it applied; 2: nothing to settle, and why (the setting is off, no gate, break-glass
// skipped it, already settled); 3: the cost was not approved but the grant is live (granted before the cost was
// decided). Landbright has no route for an application to revoke a grant (only an administrator or the holder, in
// Landbright), so the request's approvers get a task to revoke it, and the seat counts as in use, unpaid, until then.
const d = $('Ours to act on?').first().json;
const r = $input.first().json;
const gate = r.steps?.[0];
const outcome = d.outcome === 'approved' ? 'approve' : 'deny';
const base = { ...d, ref: r.ref, decisionUrl: r.decisionUrl, landbrightStatus: r.status, grant: r.grant?.status ?? null };
const how = r.method === 'break_glass' ? ' under break-glass' : r.extends ? ' (an extension approved after its grant ended)' : '';
if (d.outcome === 'approved' && r.grant?.status === 'active') {
  return [{ json: { ...base, route: 1, note: `Granted in Landbright as ${r.ref}${how}; the cost was approved after` } }];
}
if (d.outcome !== 'approved' && r.grant?.status === 'active') {
  const people = new Map();
  for (const step of r.steps ?? []) if (step.kind === 'people') for (const p of step.approvers ?? []) if (p?.email) people.set(p.email.toLowerCase(), { name: p.displayName ?? p.email, email: p.email });
  const approvers = [...people.values()];
  const to = approvers.length ? approvers.map((p) => p.name).join(', ') : `${r.ref}'s approvers`;
  return [{ json: { ...base, route: 3, landbrightRequestId: r.id, approvers, since: new Date().toISOString(),
    taskText: `For ${to}: Landledger did not approve this seat's cost (${d.number}: ${d.reason}), but Landbright granted the access${how} before the cost was decided. Landflow can't revoke a grant (Landbright has no route for it): revoke it here. Until then Landflow counts the seat as in use, unpaid.` } }];
}
const waiting = gate?.kind === 'external' && gate.system === 'Landledger' && r.status === 'pending' && r.currentStep === 0 && !gate.settlement;
if (!waiting) {
  const why = gate?.kind !== 'external' ? `${r.ref} has no cost gate` : gate.settlement ? `${r.ref}'s gate was settled already (${gate.settlement.outcome}, ${gate.settlement.reference?.id})` : `${r.ref} is ${r.status}${r.method === 'break_glass' ? ' (break-glass skipped the gate)' : ''}, not waiting on Landledger`;
  return [{ json: { ...base, route: 2, why } }];
}
if (!d.settle) return [{ json: { ...base, route: 2, why: `SETTLE_IN_LANDBRIGHT is off: ${r.ref} waits on Landledger until its gate's deadline` } }];
const body = {
  outcome,
  reference: { system: 'Landledger', id: d.landledgerRequestId, url: d.landledgerUrl },
  ...(outcome === 'deny' && d.reason ? { reason: String(d.reason).slice(0, 1000) } : {}),
};
return [{ json: { ...base, route: 0, body } }];

// Landbright's answer. 200: settled (the same answer again is 200 too). 409: the request moved on (break-glass skipped
// the gate, it expired, or it was settled with another answer): said, not retried. Anything else stops the run.
const item = $input.first().json;
const failed = item.error ? String(item.error.message ?? item.error) : '';
const detail = failed && item.description ? `: ${String(item.description).slice(0, 300)}` : '';
const d = $('What Landbright needs').first().json;
if (failed && !/\b409\b/.test(failed)) throw new Error(failed + detail);
return [{ json: { ref: d.ref, landledgerRequestId: d.landledgerRequestId, outcome: d.body.outcome, settled: !failed, why: failed + detail, landbrightStatus: item.status ?? null } }];

// What the seat needs now, from both systems' state (not the event). 0: apply (granted, the cost approved); 1: release
// the seat (access denied or expired with the cost approved; the grant revoked or expired); 2: cancel the cost request
// (Landbright ended the request, its gate run out waiting on Landledger among them, while Landledger had not decided);
// 3, then Raise or close: raise a seat request for an extension Landbright approved after its grant ended (the row is
// the first request's, which it rode on, and the grant it extended has gone), or close the revoke task of a seat whose
// cost was not approved once its grant is revoked or expired; else nothing.
const event = $('What happened').first().json;
const lb = $('Read the access request').first().json;
const row = $('Pick the seat request').first().json;
const ll = $input.first().json.request;
const seat = ll.seat?.status ?? 'none';
const grant = lb.grant?.status ?? null;
const ref = row.landbright_ref || lb.ref;
const base = { landledgerRequestId: ll.id, number: ll.number, ref, url: lb.decisionUrl, seat, grant, landbrightStatus: lb.status };
const names = (id) => [ll.origin, ...(ll.related ?? [])].some((x) => x?.type === 'landbright_request' && (x.id === id || x.id === lb.id));
const ext = lb.extends ?? null;
if (ext && grant === 'active' && lb.grant.id !== ext.grantId && !names(lb.ref) && [ll.origin, ...(ll.related ?? [])].some((x) => x?.type === 'landbright_request' && x.id === ext.ref)) {
  return [{ json: { ...base, route: 3, action: 'raise', settings: event.settings, landbrightRequestId: lb.id, why: `${lb.ref} was approved after ${ext.ref}'s grant ended: its new grant needs a seat of its own (${ll.number} is ${ext.ref}'s)` } }];
}
if (!names(ref)) return [{ json: { ...base, route: 3, action: 'nothing', why: `${ll.number} does not name ${ref}` } }];
const task = lb.annotations?.['landflow.seat_revoke'];
if (task?.status === 'open' && ['revoked', 'expired'].includes(grant)) {
  return [{ json: { ...base, route: 3, action: 'close', landbrightUrl: event.settings.landbrightUrl, landbrightRequestId: lb.id, app: row.app ?? '', contractId: ll.seat?.contractId ?? null, since: task.since ?? '', endedAt: lb.grant?.closedAt ?? new Date().toISOString(), closeText: `The grant was ${grant} in Landbright: the seat Landledger did not approve (${ll.number}) is no longer in use.` } }];
}
const ended = ['denied', 'cancelled', 'expired', 'superseded'].includes(lb.status);
const waited = event.waitedOn ? ` waiting on ${event.waitedOn}` : '';
if (grant === 'active' && ll.status === 'approved') return [{ json: { ...base, route: 0, action: 'apply', note: `Granted in Landbright as ${ref}` } }];
if (ended && ['draft', 'awaiting_confirmation', 'pending'].includes(ll.status)) {
  return [{ json: { ...base, route: 2, action: 'cancel', reason: `Landbright's ${ref} ${lb.status}${waited}: the seat isn't needed` } }];
}
if (ended && seat === 'reserved') return [{ json: { ...base, route: 1, action: 'release', reason: 'access_denied', note: `Access ${lb.status}${waited} in Landbright (${ref})` } }];
if (['revoked', 'expired'].includes(grant) && seat === 'applied') return [{ json: { ...base, route: 1, action: 'release', reason: 'grant_revoked', note: `Grant ${grant} in Landbright (${ref})` } }];
if (['revoked', 'expired'].includes(grant) && seat === 'reserved') return [{ json: { ...base, route: 1, action: 'release', reason: 'not_needed', note: `Grant ${grant} in Landbright before the seat was used (${ref})` } }];
return [{ json: { ...base, route: 3, action: 'nothing', why: `seat ${seat}, Landledger ${ll.status}, Landbright ${lb.status}, grant ${grant ?? 'none'}` } }];

// The request Landledger already has for this key: the one its 409 named, else the one whose origin is this Landbright
// request (after break-glass the origin is the Landbright request; otherwise the title ends with its ref).
const asked = $('Asked, or already asked').first().json;
const s = $('Costs a seat?').first().json;
const mine = $input.all().map((i) => i.json).filter((r) => r.id && r.kind === 'tool_or_seat');
const byOrigin = mine.find((r) => (r.origin?.type === 'landbright_request' && r.origin.id === s.ref)
  || (r.origin?.type === 'landflow_run' && r.origin.workflowId === $workflow.id && String(r.title ?? '').endsWith(`(${s.ref})`)));
const id = asked.existingId ?? byOrigin?.id;
if (!id) throw new Error(`Landledger has a seat request for ${s.ref} (${asked.why}), but named none and lists none of this key's for it`);
return [{ json: { requestId: id } }];

// Record it only if it is this workflow's seat request for this Landbright request: raised by this key from a run of
// this workflow (its origin, or after break-glass the related run), naming the Landbright request. The row names that
// run, which is what Ours to act on? matches a decision against.
const s = $('Costs a seat?').first().json;
const r = $input.first().json.request;
const bg = r.origin?.type === 'landbright_request' && r.origin.breakGlass === true;
const run = bg ? (r.related ?? []).find((x) => x.type === 'landflow_run') : r.origin;
const names = [r.origin, ...(r.related ?? [])].some((x) => x?.type === 'landbright_request' && x.id === s.ref);
if (r.kind !== 'tool_or_seat' || r.createdBy?.kind !== 'key' || run?.type !== 'landflow_run' || run.workflowId !== $workflow.id || !run.executionId || !names) {
  throw new Error(`${r.number} is not this workflow's seat request for ${s.ref}`);
}
return [{ json: { request: r, executionId: run.executionId, recovered: true } }];

// The seat request, raised now or found again after a 409, with the run that raised it. One already decided gets no
// "cost asked" note (Landbright would read it as undecided): the hourly reconcile tells Landbright its decision.
const x = $input.first().json;
const r = x.request;
const undecided = ['draft', 'awaiting_confirmation', 'pending'].includes(r.status);
return [{ json: { landledgerRequestId: r.id, number: r.number, status: r.status, executionId: x.executionId, recovered: x.recovered, note: !x.recovered || undecided } }];

// An extension adds time to a live grant, and Landbright sends it through the cost gate too. It rides on the first
// request's seat, and the gate is settled at once citing that request, when it changes nothing Landledger approved: that
// seat request is this flow's, its seat is held (reserved or in use), the grant is still live, and the new end comes
// before the contract's renewal. Otherwise (the grant ended, so approving gives a new grant; the seat went back; the new
// end crosses the renewal) the extension gets a seat request of its own, raised like any other. 0: ride; 1: raise.
const s = $('Costs a seat?').first().json;
const c = $('Find the contract').first().json;
const row = $('Find the first seat request').all().map((i) => i.json).find((x) => x.landledger_request_id) ?? null;
const ll = $('Get the first seat request').first().json.request ?? null;
const grant = $input.first().json;
const settings = $('What happened').first().json.settings;
const ext = s.extension;
const day = (ms) => new Date(ms).toISOString().slice(0, 10);
const end = grant.error || !grant.expiresAt ? null : Date.parse(grant.expiresAt) + ext.durationMinutes * 60000;
const renewal = c.contract?.renewalDate ?? null;
const why = [];
if (!row || !ll) why.push(`this flow raised no seat request for ${ext.ref}`);
else {
  if (![ll.origin, ...(ll.related ?? [])].some((x) => x?.type === 'landbright_request' && x.id === ext.ref)) why.push(`${ll.number} does not name ${ext.ref}`);
  if (!['approved', 'applied'].includes(ll.status) || !['reserved', 'applied'].includes(ll.seat?.status)) why.push(`${ll.number}'s seat is ${ll.seat?.status ?? 'none'} (Landledger: ${ll.status}), so the seat count would change`);
  if (ll.seat?.contractId && c.contract?.id && ll.seat.contractId !== c.contract.id) why.push(`another contract grants ${s.app} now`);
}
if (grant.error || grant.status !== 'active') why.push(`the grant is ${grant.error ? 'unreadable' : grant.status}: approving would give a new grant`);
else if (!end || !renewal) why.push('no end or renewal date to compare');
else if (day(end) >= renewal) why.push(`the new end (${day(end)}) is on or after the contract's renewal (${renewal})`);
if (why.length) return [{ json: { ...c, route: 1, rides: false, why: why.join('; ') } }];
const settle = s.gateWaiting && settings.settleInLandbright === true;
return [{ json: {
  ...c,
  route: 0,
  rides: true,
  landbrightRequestId: s.landbrightRequestId,
  ref: s.ref,
  firstRef: ext.ref,
  landledgerRequestId: ll.id,
  number: ll.number,
  app: s.app,
  newEnd: day(end),
  renewal,
  landbrightUrl: settings.landbrightUrl,
  settleNow: settle,
  body: { outcome: 'approve', reference: { system: 'Landledger', id: ll.id, url: `${settings.landledgerConsoleUrl}/requests/${ll.id}` } },
  text: `This extension rides on ${ext.ref}'s seat (${ll.number} in Landledger): it ends ${day(end)}, before the contract's renewal on ${renewal}, and takes no seat more.`
    + (!s.gateWaiting ? '' : settle ? ` Its cost gate is settled at once, citing ${ll.number}.` : ' SETTLE_IN_LANDBRIGHT is off: the gate waits until its deadline.'),
} }];

// Landbright's answer: 200 settled (the same answer again too); 409 the request moved on, said and not retried.
const item = $input.first().json;
const failed = item.error ? String(item.error.message ?? item.error) : '';
const d = $('Extension or new seat?').first().json;
if (failed && !/\b409\b/.test(failed)) throw new Error(failed);
return [{ json: { ref: d.ref, landledgerRequestId: d.landledgerRequestId, outcome: 'approve', settled: !failed, why: failed } }];

// The seat request recorded for this Landbright request. None: stop, unless Landbright has just activated a grant, which
// may be an extension's new grant or a break-glass grant whose request.created was missed: Costs a seat? decides.
const event = $('What happened').first().json;
const row = $input.all().map((i) => i.json).find((x) => x.landledger_request_id);
if (row) return [{ json: { ...row, route: 0 } }];
if (event.eventType === 'grant.activated') return [{ json: { route: 1, settings: event.settings, landbrightRequestId: event.landbrightRequestId } }];
return [];

// Which of this key's seat requests to look at again: those with no row (a run that stopped between Create and the
// row), and those not finished (undecided; approved and not yet used; decided against with Landbright perhaps not
// told), plus every seat counted in use, unpaid, until its grant goes. Requests older than RECENT_DAYS are left, except
// those unpaid seats.
const RECENT_DAYS = 35;
const rows = $('Seat requests on record').all().map((i) => i.json).filter((x) => x.landledger_request_id);
const unpaid = $input.all().map((i) => i.json).filter((x) => x.landledger_request_id && x.status === 'in_use');
const since = Date.now() - RECENT_DAYS * 86400000;
return $('Our seat requests').all().map((i) => i.json).filter((r) => {
  if (!r.id || r.kind !== 'tool_or_seat') return false;
  if (unpaid.some((x) => x.landledger_request_id === r.id)) return true;
  if (Date.parse(r.createdAt ?? 0) < since) return false;
  return !(rows.some((x) => x.landledger_request_id === r.id) && ['applied', 'cancelled'].includes(r.status));
}).map((r) => ({ json: { requestId: r.id } }));

// Only this workflow's seat requests (raised by this key from a run of it: the origin, or after break-glass the related
// run), each with the Landbright request it names and the run that raised it.
const out = [];
for (const item of $input.all()) {
  const r = item.json.request;
  if (!r) continue;
  const bg = r.origin?.type === 'landbright_request' && r.origin.breakGlass === true;
  const run = bg ? (r.related ?? []).find((x) => x.type === 'landflow_run') : r.origin;
  const ref = bg ? r.origin.id : (r.related ?? []).find((x) => x.type === 'landbright_request')?.id;
  if (r.kind !== 'tool_or_seat' || r.createdBy?.kind !== 'key' || run?.type !== 'landflow_run' || run.workflowId !== $workflow.id || !ref) continue;
  out.push({ json: { request: r, ref, executionId: run.executionId ?? null } });
}
return out;

// For each seat request, from both systems as they stand: record it when no row does (with the run that raised it),
// tell Landbright a decision it was never told (and settle the gate, when the setting is on and it still waits), then
// what the seat needs, as What the seat needs decides it: use it, release it, cancel a cost request whose Landbright
// request ended first (a cancel that raced the Create), give the approvers a revoke task for a live grant whose cost
// was not approved, or close that task once the grant has gone. Whatever can't be read is logged and left.
const settings = $('What happened').first().json.settings;
const rows = $('Seat requests on record').all().map((i) => i.json).filter((x) => x.landledger_request_id);
const unpaid = $('Unpaid seats').all().map((i) => i.json).filter((x) => x.landledger_request_id && x.status === 'in_use');
const refs = $('Ours, with their Landbright request').all();
const ENDED = ['denied', 'cancelled', 'expired', 'superseded'];
const out = [];
const add = (json) => out.push({ json });
$input.all().forEach((item, i) => {
  const { request: r, ref, executionId } = refs[i].json;
  const lb = item.json;
  if (lb.error || lb.ref !== ref) {
    console.log(`${r.number}: Landbright's ${ref} could not be read (${String(lb.error?.message ?? lb.error ?? 'another request answered')})`);
    return;
  }
  const base = { landledgerRequestId: r.id, number: r.number, ref, url: lb.decisionUrl, landbrightRequestId: lb.id, landbrightUrl: settings.landbrightUrl, app: lb.costs?.find((c) => c.kind === 'seat')?.landbrightApp ?? '', contractId: r.seat?.contractId ?? null };
  if (!rows.some((x) => x.landledger_request_id === r.id && x.landbright_request_id === lb.id)) {
    add({ ...base, action: 'remember', executionId, raisedAt: r.createdAt ?? new Date().toISOString(), why: `${r.number} has no row: the run that raised it (${executionId}) stopped before recording it` });
  }
  const approved = ['approved', 'applied'].includes(r.status);
  const denied = ['rejected', 'expired'].includes(r.status) || (r.status === 'cancelled' && lb.status === 'pending');
  const noted = lb.annotations?.['landflow.seat_cost']?.status ?? null;
  const decision = (r.decisions ?? []).at(-1);
  const reason = approved ? '' : decision?.comment ? `${decision.person?.name ?? 'The approver'}: ${decision.comment}` : `the cost request was ${r.status}`;
  if ((approved && noted !== 'cost_approved') || (denied && noted !== 'cost_denied')) {
    const gate = lb.steps?.[0];
    const waiting = gate?.kind === 'external' && gate.system === 'Landledger' && lb.status === 'pending' && lb.currentStep === 0 && !gate.settlement;
    add({ ...base, action: 'note', outcome: approved ? 'approved' : 'denied', reason, settle: waiting && settings.settleInLandbright === true,
      body: { outcome: approved ? 'approve' : 'deny', reference: { system: 'Landledger', id: r.id, url: `${settings.landledgerConsoleUrl}/requests/${r.id}` }, ...(approved ? {} : { reason: reason.slice(0, 1000) }) },
      why: `Landledger: ${r.status}; Landbright was told ${noted ?? 'nothing'}` });
  }
  const seat = r.seat?.status ?? 'none';
  const grant = lb.grant?.status ?? null;
  const gone = ['revoked', 'expired'].includes(grant);
  const ended = ENDED.includes(lb.status);
  const task = lb.annotations?.['landflow.seat_revoke'];
  if (task?.status === 'open' && gone) {
    add({ ...base, action: 'close', since: task.since ?? '', endedAt: lb.grant?.closedAt ?? new Date().toISOString(), closeText: `The grant was ${grant} in Landbright: the seat Landledger did not approve (${r.number}) is no longer in use.` });
  } else if (r.status === 'approved' && grant === 'active') {
    add({ ...base, action: 'apply', note: `Granted in Landbright as ${ref} (found by the hourly reconcile)` });
  } else if (['draft', 'awaiting_confirmation', 'pending'].includes(r.status) && ended) {
    add({ ...base, action: 'cancel', reason: `Landbright's ${ref} ${lb.status}: the seat isn't needed` });
  } else if (ended && seat === 'reserved') {
    add({ ...base, action: 'release', reason: 'access_denied', note: `Access ${lb.status} in Landbright (${ref})` });
  } else if (gone && seat === 'applied') {
    add({ ...base, action: 'release', reason: 'grant_revoked', note: `Grant ${grant} in Landbright (${ref})` });
  } else if (gone && seat === 'reserved') {
    add({ ...base, action: 'release', reason: 'not_needed', note: `Grant ${grant} in Landbright before the seat was used (${ref})` });
  } else if (denied && grant === 'active' && task?.status !== 'open' && !unpaid.some((x) => x.landledger_request_id === r.id)) {
    const people = new Map();
    for (const step of lb.steps ?? []) if (step.kind === 'people') for (const p of step.approvers ?? []) if (p?.email) people.set(p.email.toLowerCase(), { name: p.displayName ?? p.email, email: p.email });
    const approvers = [...people.values()];
    const to = approvers.length ? approvers.map((p) => p.name).join(', ') : `${ref}'s approvers`;
    const how = lb.method === 'break_glass' ? ' under break-glass' : lb.extends ? ' (an extension approved after its grant ended)' : '';
    add({ ...base, action: 'revoke', reason, approvers, since: new Date().toISOString(),
      taskText: `For ${to}: Landledger did not approve this seat's cost (${r.number}: ${reason}), but Landbright granted the access${how} before the cost was decided. Landflow can't revoke a grant (Landbright has no route for it): revoke it here. Until then Landflow counts the seat as in use, unpaid.` });
  }
});
return out;
